//! These are disposable owner readings, not a semantic store. The kernel
//! retains them in OwnerReadCache; each input can be requested independently
//! so local navigation never waits for an optional hosted-field request.

/// Independently loadable inputs. `All` preserves the earlier request shape;
/// the Wiki UI asks for the specific native inputs it actually displays.
#[derive(Clone, Copy, Debug, Default, Deserialize, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum InputSelection { #[default] All, CentralWiki, AikitResolution, SharedField }
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct ReadOptions {
    #[serde(default)] pub input: InputSelection,
    #[serde(default)] pub fresh: bool,
    #[serde(default = "node_budget")] pub max_nodes: usize,
    #[serde(default = "edge_budget")] pub max_edges: usize,
}
fn node_budget() -> usize { 4096 }
fn edge_budget() -> usize { 16384 }
impl Default for ReadOptions { fn default() -> Self { Self { input: InputSelection::All, fresh: false, max_nodes: node_budget(), max_edges: edge_budget() } } }
impl ReadOptions {
    pub fn validate(&self) -> Result<(), String> {
        if !(1..=20_000).contains(&self.max_nodes) || !(1..=100_000).contains(&self.max_edges) { return Err("Graph budgets require 1..=20000 nodes and 1..=100000 edges".into()); }
        Ok(())
    }
}

