/// Consume the native metadata graph, retaining typed addresses, occurrence
/// identity and constellation membership instead of inventing them in React.
fn assemble_native_knowledge(reading: &mut GraphReading, cwd: &Path, query: &str, options: &ReadOptions) {
    let nodes = options.max_nodes.to_string();
    let edges = options.max_edges.to_string();
    let data = knowledge::run(cwd, &["knowledge", "graph", "--max-nodes", &nodes, "--max-edges", &edges, "--", query]);
    match data {
        Ok(data) => {
            if data["schema"] != "aikit.knowledge-graph/v1" || !data["nodes"].is_array() || !data["edges"].is_array() {
                reading.inputs.aikit_resolution = GraphInput::Unavailable { owner_operation: "aikit.knowledge.graph".into(), detail: "Native graph returned an unsupported schema".into() }; return;
            }
            adapt_native_graph(reading, &data);
        }
        Err(error) => reading.inputs.aikit_resolution = GraphInput::Unavailable {owner_operation: "aikit.knowledge.graph".into(), detail: format!("Native Wiki graph unavailable: {error:?}")},
    }
}

pub fn adapt_native_graph(reading: &mut GraphReading, data: &Value) {
    reading.inputs.aikit_resolution = GraphInput::Available {owner_operation: "aikit.knowledge.graph".into(), detail: data.get("absences").filter(|v|v.as_array().is_some_and(|a| !a.is_empty())).map(ToString::to_string)};
    for node in data["nodes"].as_array().into_iter().flatten() {
        let Some(reference) = node["resource"].as_str().filter(|r| !r.is_empty()) else { continue; };
        let mut metadata = std::collections::BTreeMap::new();
        for field in ["address", "tags", "aliases"] { if let Some(value) = node.get(field) { metadata.insert(field.to_string(), value.clone()); } }
        reading.nodes.push(GraphNode {ref_id:reference.into(), label:node["label"].as_str().unwrap_or(reference).into(), kind:node["kind"].as_str().unwrap_or("knowledge-subject").into(), native_owner:"ai-kit".into(), provenance:GraphProvenance {source:"aikit.knowledge.graph".into(),revision:node["revision"].as_str().map(str::to_owned), detail:["provider","authority"].iter().filter_map(|key| node[*key].as_str().map(str::to_owned)).collect()}, actions:Vec::new(), metadata});
    }
    for edge in data["edges"].as_array().into_iter().flatten() {
        let (Some(from),Some(to),Some(relation)) = (edge["from"].as_str(),edge["to"].as_str(),edge["relation"].as_str()) else {continue;};
        let mut metadata = std::collections::BTreeMap::new();
        for field in ["reference", "authored_relation", "origin", "containment"] { if let Some(value) = edge.get(field).filter(|v| !v.is_null()) { metadata.insert(field.to_string(),value.clone()); } }
        reading.edges.push(GraphEdge {from_ref:from.into(),to_ref:to.into(),relation:relation.into(),provenance:GraphProvenance {source:"aikit.knowledge.graph".into(),revision:edge["origin"]["revision"].as_str().map(str::to_owned),detail:Vec::new()},metadata});
    }
    reading.formations = data["formations"].as_array().cloned().unwrap_or_default();
    reading.truncated = data["truncated"] == true;
    reading.counts.knowledge_rows = reading.nodes.len();
    reading.counts.nodes = reading.nodes.len();
    reading.counts.edges = reading.edges.len();
}

#[cfg(test)]
mod native_graph_tests {
    use super::*;
    #[test]
    fn native_addresses_occurrences_and_partial_wholes_survive_adaptation() {
        let mut reading=GraphReading::empty();
        let value=serde_json::json!({"nodes":[{"resource":"source:a","kind":"knowledge-source","label":"A","address":{"kind":"source","value":"source:a"},"tags":["reading"],"revision":"r1"}],"edges":[{"reference":"edge:one","from":"source:a","to":"source:a","relation":"references","authored_relation":{"source_ref":"source:a","anchor":{"start_byte":4,"end_byte":9}},"origin":{"revision":"1"}}],"formations":[{"ref":"frame:a","partial":true,"members":[{"ref":"source:a","role":"0"}]}],"truncated":true});
        adapt_native_graph(&mut reading,&value);
        let wire=serde_json::to_value(reading).unwrap();
        assert_eq!(wire["nodes"][0]["address"]["kind"],"source");
        assert_eq!(wire["edges"][0]["reference"],"edge:one");
        assert_eq!(wire["formations"][0]["partial"],true);
        assert_eq!(wire["truncated"],true);
    }
    #[test]
    fn graph_budgets_are_explicit_and_bounded() {
        assert!(ReadOptions::default().validate().is_ok());
        assert!(ReadOptions {max_nodes:0,..ReadOptions::default()}.validate().is_err());
        assert!(ReadOptions {max_edges:100_001,..ReadOptions::default()}.validate().is_err());
    }
}
